// docs/NAV.md#corridor-snap
export interface PathTileLike {
    x: number;
    z: number;
    level: number;
}

export const chebyshev = (a: { x: number; z: number }, b: { x: number; z: number }): number => Math.max(Math.abs(a.x - b.x), Math.abs(a.z - b.z));

export function isOnFarSide(me: PathTileLike | null, approach: PathTileLike, step: PathTileLike): boolean {
    return me !== null && me.level === step.level && chebyshev(me, step) < chebyshev(me, approach);
}

export function locateOnPath(tiles: PathTileLike[], me: PathTileLike, fromIdx: number, window: number, corridor: number, limitIdx = tiles.length - 1): number {
    let found = -1;
    for (let i = fromIdx; i < Math.min(fromIdx + window, tiles.length, limitIdx + 1); i++) {
        if (tiles[i].level === me.level && chebyshev(tiles[i], me) <= corridor) {
            found = i;
        }
    }
    return found;
}

export function selectClickTarget(tiles: PathTileLike[], pathIdx: number, steps: number, limitIdx: number, level: number, isClickable: (t: PathTileLike) => boolean): number {
    const top = Math.min(pathIdx + steps, limitIdx, tiles.length - 1);
    for (let i = top; i > pathIdx; i--) {
        if (tiles[i].level !== level) {
            continue;
        }
        if (isClickable(tiles[i])) {
            return i;
        }
    }
    return -1;
}

/**
 * Prefer the furthest click that the client walk/pathfind accepts.
 * Walks from far→near so a failed `tryMove` (or equivalent) falls back to a
 * closer path tile instead of waiting for stall ticks.
 *
 * `tryWalk(i)` should issue the client walk for tiles[i] and return whether the
 * client accepted a route (e.g. `tryMove` / `driver.walk`). Side effects of a
 * successful walk are intentional — caller uses the returned index as clickIdx.
 */
export function selectClientWalkTarget(
    tiles: PathTileLike[],
    pathIdx: number,
    steps: number,
    limitIdx: number,
    level: number,
    isClickable: (t: PathTileLike) => boolean,
    tryWalk: (tileIndex: number) => boolean
): number {
    const top = Math.min(pathIdx + steps, limitIdx, tiles.length - 1);
    for (let i = top; i > pathIdx; i--) {
        if (tiles[i].level !== level) {
            continue;
        }
        if (!isClickable(tiles[i])) {
            continue;
        }
        if (tryWalk(i)) {
            return i;
        }
    }
    return -1;
}

export function starvedTerminalIndex(tiles: PathTileLike[], me: PathTileLike, isClickable: (t: PathTileLike) => boolean): number {
    const last = tiles.length - 1;
    if (last < 0) {
        return -1;
    }
    const end = tiles[last];
    if (end.level !== me.level || (end.x === me.x && end.z === me.z)) {
        return -1;
    }
    return isClickable(end) ? last : -1;
}

export function crossingEligible(me: PathTileLike, approach: PathTileLike, far: PathTileLike, trigger: number, reachable: (t: PathTileLike) => boolean): boolean {
    if (me.level !== approach.level) {
        return false;
    }
    if (chebyshev(me, approach) > trigger && chebyshev(me, far) > trigger) {
        return false;
    }
    return reachable(approach);
}

export function chooseCrossClick(canStepEdge: boolean, canReachLanding: boolean): 'step' | 'landing-click' | 'landing-scene' {
    if (canStepEdge) {
        return 'step';
    }
    return canReachLanding ? 'landing-click' : 'landing-scene';
}

export function shouldApproachClosedBarrier(me: PathTileLike | null, approach: PathTileLike, closed: boolean): boolean {
    return closed && me !== null && (me.x !== approach.x || me.z !== approach.z || me.level !== approach.level);
}

/**
 * Stall recovery: furthest clickable / corridor tile ahead on the published path
 * (rs2b0t findForwardRecoveryIndex). Prefer re-click on path over immediate repath.
 */
export function findForwardRecoveryIndex(
    tiles: PathTileLike[],
    me: PathTileLike,
    fromIdx: number,
    isClickable: (t: PathTileLike) => boolean,
    opts?: { corridor?: number; window?: number; limitIdx?: number }
): number {
    if (tiles.length === 0) return -1;
    const corridor = opts?.corridor ?? 3;
    const window = opts?.window ?? 40;
    const limitIdx = Math.min(opts?.limitIdx ?? tiles.length - 1, tiles.length - 1);
    const hi = Math.min(fromIdx + window, limitIdx);
    let bestClickable = -1;
    let bestOnCorridor = -1;
    for (let i = fromIdx + 1; i <= hi; i++) {
        const t = tiles[i]!;
        if (t.level !== me.level) continue;
        if (t.x === me.x && t.z === me.z) continue;
        if (chebyshev(me, t) <= corridor) bestOnCorridor = i;
        if (isClickable(t)) bestClickable = i;
    }
    if (bestClickable !== -1) return bestClickable;
    return bestOnCorridor;
}
